def f(inputs: List[Tuple[int, int, str, str, str]]):
    output = []
    for l, d, s1, s2, s3 in inputs:
        if l == 0 and d == 0:
            break
        diff_s1_s2 = sum(a!= b for a, b in zip(s1, s2))
        diff_s2_s3 = sum(a!= b for a, b in zip(s2, s3))
        diff_s1_s3 = sum(a!= b for a, b in zip(s1, s3))
        if (diff_s1_s2 <= d and diff_s2_s3 <= d) or (diff_s1_s2 + diff_s2_s3 <= d):
            output.append('A')
        elif diff_s1_s3 <= d:
            output.append('B')
        else:
            output.append('C')
    return output
```

